// Role templates: complete starting points for the school's common hires. Each is written for its own age band
// or function, with three question variants per competency and scenarios whose real issue is hidden under the
// surface. Everything is editable in the role form before the requisition is submitted.
import { DEFAULT_SCENARIOS, DEFAULT_RUBRICS } from "./db.js";

const Q = (assesses, ...texts) => texts.map((text) => ({ text, assesses }));
const RP = (id, title, assesses, persona, surface, underlying, observe) => ({ id, type: "roleplay", title, assesses, persona, surface, underlying, observe });
const SIT = (id, title, assesses, setup, twist, observe) => ({ id, type: "situation", title, assesses, setup, twist, observe });
const R = (...items) => items.map(([key, label]) => ({ key, label }));
const CRIT = (...items) => items.map(([text, must], i) => ({ id: `c${i + 1}`, text, must: must ? 1 : 0 }));
const base = { openings: 1, interview_mode: "interactive", max_questions: 4, answer_seconds: 90, languages: ["en"], salary_band: "" };
const ADMIN_RUBRICS = { "Leadership interview": R(["fit", "Fit with school culture and values"], ["communication", "Communication with parents, children and colleagues"], ["ownership", "Ownership and follow-through"], ["growth", "Openness to feedback"]), "Subject assessment": R(["skill", "Skills test: accuracy and speed on the role's core tasks"], ["systems", "Comfort with the school's systems and tools"], ["judgement", "Judgement on what to escalate"]), "Demo lesson": R(["task", "Practical task: quality of the output"], ["process", "Process followed and documentation"], ["pressure", "Composure under time pressure"], ["service", "Service manner in the task"]) };

